import * as React from "react"
import { TrendingUp, TrendingDown, Minus } from "lucide-react"

import { cn } from "@/lib/utils"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"

export interface StatItem {
  id?: string
  title: string
  value: string | number
  change?: {
    value: string
    type: "increase" | "decrease" | "neutral"
  }
  description?: string
  icon?: React.ComponentType<{ className?: string }>
}

export interface StatsGridProps {
  stats: StatItem[]
  columns?: 2 | 3 | 4
  className?: string
}

export function StatCard({ item }: { item: StatItem }) {
  const Icon = item.icon

  return (
    <Card className="relative overflow-hidden">
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium text-muted-foreground">
          {item.title}
        </CardTitle>
        {Icon && (
          <div className="flex h-8 w-8 items-center justify-center rounded-md bg-muted text-muted-foreground">
            <Icon className="h-4 w-4" />
          </div>
        )}
      </CardHeader>
      <CardContent>
        <div className="text-2xl font-bold tracking-tight">{item.value}</div>

        {(item.change || item.description) && (
          <div className="mt-2 flex items-center gap-2 text-xs">
            {item.change && (
              <Badge
                variant={
                  item.change.type === "increase"
                    ? "success"
                    : item.change.type === "decrease"
                    ? "destructive"
                    : "secondary"
                }
                className="gap-1 px-1.5 py-0 font-medium"
              >
                {item.change.type === "increase" && <TrendingUp className="h-3 w-3" />}
                {item.change.type === "decrease" && <TrendingDown className="h-3 w-3" />}
                {item.change.type === "neutral" && <Minus className="h-3 w-3" />}
                <span>{item.change.value}</span>
              </Badge>
            )}
            {item.description && (
              <span className="text-muted-foreground truncate">{item.description}</span>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

export function StatsGrid({ stats, columns = 4, className }: StatsGridProps) {
  const gridColsClass =
    columns === 2
      ? "sm:grid-cols-2"
      : columns === 3
      ? "sm:grid-cols-2 lg:grid-cols-3"
      : "sm:grid-cols-2 lg:grid-cols-4"

  return (
    <div className={cn("grid grid-cols-1 gap-4", gridColsClass, className)}>
      {stats.map((stat, idx) => (
        <StatCard key={stat.id ?? idx} item={stat} />
      ))}
    </div>
  )
}

import * as React from "react"
import { Search, X, SlidersHorizontal, Plus, Download, Check } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Separator } from "@/components/ui/separator"

export interface FilterOption {
  label: string
  value: string
  icon?: React.ComponentType<{ className?: string }>
  count?: number
}

export interface DataTableToolbarProps {
  searchValue?: string
  onSearchChange?: (value: string) => void
  searchPlaceholder?: string
  filterTitle?: string
  filterOptions?: FilterOption[]
  selectedFilters?: string[]
  onFilterToggle?: (value: string) => void
  columns?: { id: string; label: string; visible: boolean }[]
  onColumnToggle?: (columnId: string) => void
  onResetFilters?: () => void
  onExport?: () => void
  onAdd?: () => void
  addLabel?: string
  className?: string
}

export function DataTableToolbar({
  searchValue = "",
  onSearchChange,
  searchPlaceholder = "Filter records...",
  filterTitle = "Status",
  filterOptions = [],
  selectedFilters = [],
  onFilterToggle,
  columns = [],
  onColumnToggle,
  onResetFilters,
  onExport,
  onAdd,
  addLabel = "Add Record",
  className,
}: DataTableToolbarProps) {
  const isFiltered = searchValue.length > 0 || selectedFilters.length > 0

  return (
    <div className={cn("flex flex-wrap items-center justify-between gap-3", className)}>
      <div className="flex flex-1 flex-wrap items-center gap-2">
        {/* Search input */}
        <div className="relative w-full sm:w-64">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            value={searchValue}
            onChange={(e) => onSearchChange?.(e.target.value)}
            placeholder={searchPlaceholder}
            className="pl-9 h-9 text-xs"
          />
          {searchValue && (
            <button
              onClick={() => onSearchChange?.("")}
              className="absolute right-2.5 top-2.5 text-muted-foreground hover:text-foreground"
            >
              <X className="h-4 w-4" />
            </button>
          )}
        </div>

        {/* Faceted Filter */}
        {filterOptions.length > 0 && (
          <Popover>
            <PopoverTrigger asChild>
              <Button variant="outline" size="sm" className="h-9 border-dashed text-xs gap-1.5">
                <span>{filterTitle}</span>
                {selectedFilters.length > 0 && (
                  <>
                    <Separator orientation="vertical" className="mx-1 h-4" />
                    <Badge variant="secondary" className="rounded-sm px-1 font-normal text-[10px]">
                      {selectedFilters.length}
                    </Badge>
                  </>
                )}
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-52 p-1" align="start">
              <div className="flex flex-col gap-1">
                {filterOptions.map((option) => {
                  const isSelected = selectedFilters.includes(option.value)
                  return (
                    <button
                      key={option.value}
                      type="button"
                      onClick={() => onFilterToggle?.(option.value)}
                      className={cn(
                        "flex items-center gap-2 rounded-sm px-2 py-1.5 text-xs transition-colors hover:bg-muted text-left",
                        isSelected && "font-semibold text-foreground"
                      )}
                    >
                      <div
                        className={cn(
                          "flex h-4 w-4 items-center justify-center rounded-sm border border-primary",
                          isSelected ? "bg-primary text-primary-foreground" : "opacity-50"
                        )}
                      >
                        {isSelected && <Check className="h-3 w-3" />}
                      </div>
                      <span className="flex-1 truncate">{option.label}</span>
                      {option.count !== undefined && (
                        <span className="text-muted-foreground font-mono text-[10px]">
                          {option.count}
                        </span>
                      )}
                    </button>
                  )
                })}
              </div>
            </PopoverContent>
          </Popover>
        )}

        {/* Reset button */}
        {isFiltered && onResetFilters && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onResetFilters}
            className="h-9 px-2 text-xs text-muted-foreground hover:text-foreground"
          >
            Reset
            <X className="ml-1 h-3.5 w-3.5" />
          </Button>
        )}
      </div>

      <div className="flex items-center gap-2">
        {/* Column view options */}
        {columns.length > 0 && onColumnToggle && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="sm" className="h-9 gap-1.5 text-xs">
                <SlidersHorizontal className="h-3.5 w-3.5" />
                <span>View</span>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-44">
              <DropdownMenuLabel className="text-xs">Toggle columns</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {columns.map((column) => (
                <DropdownMenuCheckboxItem
                  key={column.id}
                  checked={column.visible}
                  onCheckedChange={() => onColumnToggle(column.id)}
                  className="text-xs capitalize"
                >
                  {column.label}
                </DropdownMenuCheckboxItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        )}

        {/* Export button */}
        {onExport && (
          <Button variant="outline" size="sm" onClick={onExport} className="h-9 gap-1.5 text-xs">
            <Download className="h-3.5 w-3.5" />
            <span className="hidden sm:inline">Export</span>
          </Button>
        )}

        {/* Add CTA */}
        {onAdd && (
          <Button size="sm" onClick={onAdd} className="h-9 gap-1.5 text-xs">
            <Plus className="h-3.5 w-3.5" />
            <span>{addLabel}</span>
          </Button>
        )}
      </div>
    </div>
  )
}

import * as React from "react"
import { FolderPlus, LucideIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export interface EmptyStateProps {
  icon?: LucideIcon | React.ComponentType<{ className?: string }>
  title: string
  description?: string
  action?: {
    label: string
    onClick?: () => void
    href?: string
  }
  secondaryAction?: {
    label: string
    onClick?: () => void
    href?: string
  }
  className?: string
  children?: React.ReactNode
}

export function EmptyState({
  icon: Icon = FolderPlus,
  title,
  description,
  action,
  secondaryAction,
  className,
  children,
}: EmptyStateProps) {
  return (
    <div
      className={cn(
        "flex min-h-[360px] flex-col items-center justify-center rounded-xl border border-dashed p-8 text-center animate-in fade-in-50",
        className
      )}
    >
      <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-muted/60 text-muted-foreground ring-8 ring-muted/30">
        <Icon className="h-7 w-7" />
      </div>

      <h3 className="mt-5 text-lg font-semibold tracking-tight text-foreground">
        {title}
      </h3>

      {description && (
        <p className="mt-2 text-sm text-muted-foreground max-w-sm text-balance">
          {description}
        </p>
      )}

      {(action || secondaryAction || children) && (
        <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
          {action && (
            <Button
              size="sm"
              onClick={action.onClick}
              asChild={!!action.href}
            >
              {action.href ? <a href={action.href}>{action.label}</a> : action.label}
            </Button>
          )}

          {secondaryAction && (
            <Button
              variant="outline"
              size="sm"
              onClick={secondaryAction.onClick}
              asChild={!!secondaryAction.href}
            >
              {secondaryAction.href ? (
                <a href={secondaryAction.href}>{secondaryAction.label}</a>
              ) : (
                secondaryAction.label
              )}
            </Button>
          )}

          {children}
        </div>
      )}
    </div>
  )
}

import * as React from "react"
import { Search, FileText, Settings, User, LogOut, Moon, Sun, Laptop } from "lucide-react"

import { cn } from "@/lib/utils"
import { Dialog, DialogContent } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"

export interface CommandItem {
  id: string
  title: string
  icon?: React.ComponentType<{ className?: string }>
  shortcut?: string
  onSelect: () => void
}

export interface CommandGroup {
  heading: string
  items: CommandItem[]
}

export interface CommandMenuProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  groups?: CommandGroup[]
  placeholder?: string
}

const DEFAULT_GROUPS: CommandGroup[] = [
  {
    heading: "Quick Navigation",
    items: [
      { id: "docs", title: "Documentation", icon: FileText, shortcut: "G D", onSelect: () => {} },
      { id: "settings", title: "Project Settings", icon: Settings, shortcut: "G S", onSelect: () => {} },
      { id: "profile", title: "User Profile", icon: User, shortcut: "G P", onSelect: () => {} },
    ],
  },
  {
    heading: "System Actions",
    items: [
      { id: "logout", title: "Log out", icon: LogOut, onSelect: () => {} },
    ],
  },
]

export function CommandMenu({
  open,
  onOpenChange,
  groups = DEFAULT_GROUPS,
  placeholder = "Type a command or search...",
}: CommandMenuProps) {
  const [query, setQuery] = React.useState("")

  React.useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === "k" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault()
        onOpenChange(!open)
      }
    }

    document.addEventListener("keydown", down)
    return () => document.removeEventListener("keydown", down)
  }, [open, onOpenChange])

  const filteredGroups = groups
    .map((group) => ({
      ...group,
      items: group.items.filter((item) =>
        item.title.toLowerCase().includes(query.toLowerCase())
      ),
    }))
    .filter((group) => group.items.length > 0)

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="overflow-hidden p-0 max-w-xl shadow-2xl">
        <div className="flex items-center border-b px-3">
          <Search className="mr-2 h-4 w-4 shrink-0 text-muted-foreground" />
          <input
            className="flex h-11 w-full rounded-md bg-transparent py-3 text-sm outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50"
            placeholder={placeholder}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>

        <div className="max-h-[300px] overflow-y-auto p-2">
          {filteredGroups.length === 0 ? (
            <p className="p-4 text-center text-sm text-muted-foreground">
              No results found for &ldquo;{query}&rdquo;.
            </p>
          ) : (
            filteredGroups.map((group, idx) => (
              <div key={idx} className="mb-2 last:mb-0">
                <span className="px-2 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
                  {group.heading}
                </span>
                <div className="mt-1 flex flex-col gap-0.5">
                  {group.items.map((item) => {
                    const Icon = item.icon
                    return (
                      <button
                        key={item.id}
                        type="button"
                        onClick={() => {
                          item.onSelect()
                          onOpenChange(false)
                        }}
                        className="flex w-full items-center gap-2 rounded-md px-2.5 py-1.5 text-xs text-foreground transition-colors hover:bg-accent hover:text-accent-foreground text-left"
                      >
                        {Icon && <Icon className="h-4 w-4 shrink-0 text-muted-foreground" />}
                        <span className="flex-1 truncate">{item.title}</span>
                        {item.shortcut && (
                          <kbd className="pointer-events-none rounded border bg-muted px-1.5 py-0.5 font-mono text-[10px] text-muted-foreground">
                            {item.shortcut}
                          </kbd>
                        )}
                      </button>
                    )
                  })}
                </div>
              </div>
            ))
          )}
        </div>

        <div className="border-t bg-muted/40 px-3 py-2 flex items-center justify-between text-[11px] text-muted-foreground">
          <span>Navigate with arrows</span>
          <span>Esc to close</span>
        </div>
      </DialogContent>
    </Dialog>
  )
}

import * as React from "react"
import { AlertTriangle, Loader2 } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"

export interface ConfirmDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description: string
  confirmText?: string
  cancelText?: string
  variant?: "destructive" | "default"
  requireConfirmationText?: string
  loading?: boolean
  onConfirm: () => void | Promise<void>
}

export function ConfirmDialog({
  open,
  onOpenChange,
  title,
  description,
  confirmText = "Delete",
  cancelText = "Cancel",
  variant = "destructive",
  requireConfirmationText,
  loading = false,
  onConfirm,
}: ConfirmDialogProps) {
  const [inputText, setInputText] = React.useState("")
  const isMatch = requireConfirmationText ? inputText === requireConfirmationText : true

  React.useEffect(() => {
    if (!open) {
      setInputText("")
    }
  }, [open])

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader className="gap-2 sm:text-left">
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-destructive/10 text-destructive ring-8 ring-destructive/5">
            <AlertTriangle className="h-5 w-5" />
          </div>
          <DialogTitle className="text-lg">{title}</DialogTitle>
          <DialogDescription className="text-sm">{description}</DialogDescription>
        </DialogHeader>

        {requireConfirmationText && (
          <div className="my-2 space-y-2">
            <p className="text-xs text-muted-foreground">
              Please type <span className="font-semibold text-foreground">{requireConfirmationText}</span> to confirm:
            </p>
            <Input
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder={requireConfirmationText}
              className="text-xs"
              autoFocus
            />
          </div>
        )}

        <DialogFooter className="gap-2 sm:gap-0 mt-4">
          <Button
            variant="outline"
            size="sm"
            onClick={() => onOpenChange(false)}
            disabled={loading}
          >
            {cancelText}
          </Button>
          <Button
            variant={variant}
            size="sm"
            onClick={onConfirm}
            disabled={!isMatch || loading}
          >
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {confirmText}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

